import { AGENT_SIDEBAR_QUERY_PARAM, AGENT_SIDEBAR_QUERY_VALUE_CLOSED, AGENT_SIDEBAR_QUERY_VALUE_OPEN, } from "../shared/agent-sidebar-url.js";
import { hasChatThreadDeepLink } from "./chat-thread-url.js";
export { hasChatThreadDeepLink } from "./chat-thread-url.js";
export const SIDEBAR_OPEN_KEY = "agent-native-sidebar-open";
export const SIDEBAR_STATE_CHANGE_EVENT = "agent-panel:state-change";
export const SIDEBAR_URL_CHANGE_EVENT = "agent-panel:url-change";
export const AGENT_SIDEBAR_MIN_WIDTH = 280;
export const AGENT_SIDEBAR_DEFAULT_MAX_WIDTH = 700;
export const AGENT_SIDEBAR_WIDE_WIDTH_RATIO = 0.75;
const HISTORY_PATCHED_KEY = "__agentNativeSidebarHistoryPatched";
function resolveViewportWidth(viewportWidth) {
    const resolved = viewportWidth ??
        (typeof window === "undefined"
            ? AGENT_SIDEBAR_DEFAULT_MAX_WIDTH
            : window.innerWidth);
    if (!Number.isFinite(resolved)) {
        throw new TypeError("Agent sidebar viewport width must be finite");
    }
    return Math.max(0, resolved);
}
export function getAgentSidebarWideWidth(viewportWidth) {
    return Math.max(AGENT_SIDEBAR_MIN_WIDTH, Math.round(resolveViewportWidth(viewportWidth) * AGENT_SIDEBAR_WIDE_WIDTH_RATIO));
}
export function getAgentSidebarMaxWidth(viewportWidth) {
    return Math.max(AGENT_SIDEBAR_DEFAULT_MAX_WIDTH, getAgentSidebarWideWidth(viewportWidth));
}
export function clampAgentSidebarWidth(width, viewportWidth) {
    if (!Number.isFinite(width)) {
        throw new TypeError("Agent sidebar width must be finite");
    }
    return Math.min(getAgentSidebarMaxWidth(viewportWidth), Math.max(AGENT_SIDEBAR_MIN_WIDTH, width));
}
export function getAgentSidebarOpenPreferenceKey(storageKey) {
    const suffix = storageKey?.trim();
    return suffix ? `agent-native.${suffix}.sidebar-open` : SIDEBAR_OPEN_KEY;
}
export function dispatchAgentSidebarStateChange(detail) {
    if (typeof window === "undefined")
        return;
    window.dispatchEvent(new CustomEvent(SIDEBAR_STATE_CHANGE_EVENT, {
        detail,
    }));
}
export function setAgentSidebarOpenPreference(open, storageKey) {
    if (typeof window === "undefined")
        return;
    try {
        localStorage.setItem(getAgentSidebarOpenPreferenceKey(storageKey), String(open));
    }
    catch { }
}
export function requestAgentSidebarOpen() {
    if (typeof window === "undefined")
        return;
    window.dispatchEvent(new CustomEvent("agent-panel:open"));
}
export function getAgentSidebarUrlOpenOverride() {
    if (typeof window === "undefined")
        return null;
    try {
        const url = new URL(window.location.href);
        const value = url.searchParams.get(AGENT_SIDEBAR_QUERY_PARAM);
        if (value === AGENT_SIDEBAR_QUERY_VALUE_CLOSED)
            return false;
        if (value === AGENT_SIDEBAR_QUERY_VALUE_OPEN)
            return true;
    }
    catch { }
    return null;
}
export function consumeAgentSidebarUrlOpenOverride(storageKey) {
    const override = getAgentSidebarUrlOpenOverride();
    if (override === null || typeof window === "undefined")
        return override;
    setAgentSidebarOpenPreference(override, storageKey);
    try {
        const url = new URL(window.location.href);
        url.searchParams.delete(AGENT_SIDEBAR_QUERY_PARAM);
        window.history.replaceState(window.history.state, "", `${url.pathname}${url.search}${url.hash}`);
    }
    catch { }
    return override;
}
function emitSidebarUrlChange() {
    if (typeof window === "undefined")
        return;
    window.dispatchEvent(new Event(SIDEBAR_URL_CHANGE_EVENT));
}
function installSidebarUrlChangeEvents() {
    if (typeof window === "undefined")
        return;
    const historyWithFlag = window.history;
    if (historyWithFlag[HISTORY_PATCHED_KEY])
        return;
    const pushState = window.history.pushState.bind(window.history);
    const replaceState = window.history.replaceState.bind(window.history);
    window.history.pushState = function pushStateWithSidebarEvent(...args) {
        const result = pushState.apply(this, args);
        emitSidebarUrlChange();
        return result;
    };
    window.history.replaceState = function replaceStateWithSidebarEvent(...args) {
        const result = replaceState.apply(this, args);
        emitSidebarUrlChange();
        return result;
    };
    historyWithFlag[HISTORY_PATCHED_KEY] = true;
}
export function subscribeAgentSidebarUrlChanges(listener) {
    if (typeof window === "undefined")
        return () => { };
    installSidebarUrlChangeEvents();
    window.addEventListener(SIDEBAR_URL_CHANGE_EVENT, listener);
    window.addEventListener("popstate", listener);
    window.addEventListener("hashchange", listener);
    return () => {
        window.removeEventListener(SIDEBAR_URL_CHANGE_EVENT, listener);
        window.removeEventListener("popstate", listener);
        window.removeEventListener("hashchange", listener);
    };
}
export function getInitialAgentSidebarOpen(defaultOpen, storageKey) {
    const urlOverride = getAgentSidebarUrlOpenOverride();
    if (urlOverride !== null)
        return urlOverride;
    if (hasChatThreadDeepLink())
        return true;
    // On mobile viewports the sidebar would cover most of the screen, so
    // always start closed regardless of any persisted desktop preference.
    if (typeof window !== "undefined" &&
        window.matchMedia("(max-width: 767px)").matches) {
        return false;
    }
    try {
        const saved = localStorage.getItem(getAgentSidebarOpenPreferenceKey(storageKey));
        if (saved === "false")
            return false;
        // Never let durable storage turn on a sidebar that is default-closed.
        // Programmatic chat handoffs open the current sidebar transiently instead.
        if (defaultOpen && saved === "true")
            return true;
    }
    catch { }
    return defaultOpen;
}
